    # paint background cells 3, leaving all markers unchanged.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    rr, cc = r + dr, c + dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != marker:
                            out[rr][cc] = 3
                        rr += dr; cc += dc
    return out
